//! Flutter counterpart: `material/icons.dart`.
//!
//! Generated from the Dart table by a script; Dart's doc comments are kept, since they carry the
//! icons' names. The getters of `Icons.adaptive` take the app, whose platform is
//! `defaultTargetPlatform`.
//! The font itself is the Flutter SDK's `MaterialIcons-Regular.otf`, bundled under `assets/`
//! (see `assets/MaterialIcons_LICENSE.txt`) and registered by [`install_material_icon_font`].
//!
//! The table between the `BEGIN GENERATED` markers is generated: change the generator, not the
//! table.

use waft_embedder::TargetPlatform;
use waft_foundation::App;
use waft_painting::PaintingBinding;
use waft_widgets::IconData;

/// The Material Icons font, which Flutter's tool bundles into every app that sets
/// `uses-material-design: true` and this crate carries in `assets/`.
const ICON_FONT_BYTES: &[u8] = include_bytes!("../assets/MaterialIcons-Regular.otf");

/// The family every entry of the table names and the font is registered under.
const ICON_FONT_FAMILY: &str = "MaterialIcons";

/// An icon of the bundled font: every entry of the table carries the family the glyph lives in.
fn material(code_point: u32) -> IconData {
    IconData::new(code_point).font_family(ICON_FONT_FAMILY)
}

/// Registers the bundled Material Icons font with the app-wide font collection, which is what
/// `uses-material-design: true` in `pubspec.yaml` does in Flutter.
///
/// Call it once at start-up, before a tree that shows an icon is built. Calling it again does
/// nothing.
pub fn install_material_icon_font(app: &mut App) {
    let binding = PaintingBinding::instance(app);
    if binding.has_fonts(app)
        && app
            .get(binding.fonts(app))
            .family(ICON_FONT_FAMILY)
            .is_some()
    {
        return;
    }
    binding
        .register_font(app, ICON_FONT_FAMILY, ICON_FONT_BYTES.to_vec())
        .expect("the bundled Material icons font parses");
}

