#[cfg(test)]
mod tests {
    use waft_embedder::{FontCollection, TextDirection};
    use waft_foundation::Handle;
    use waft_painting::{TextPainter, TextSpan, TextStyle};

    use super::*;
    use std::rc::Rc;

    use waft_foundation::AppCell;
    use waft_test::TestPlatform;

    const CUPERTINO_PLATFORMS: [TargetPlatform; 2] = [TargetPlatform::IOS, TargetPlatform::MacOS];
    const OTHER_PLATFORMS: [TargetPlatform; 4] = [
        TargetPlatform::Android,
        TargetPlatform::Fuchsia,
        TargetPlatform::Windows,
        TargetPlatform::Linux,
    ];

    fn installed_fonts(app: &mut App) -> Handle<FontCollection> {
        install_material_icon_font(app);
        PaintingBinding::instance(app).fonts(app)
    }

    /// What an `Icon` widget styles its glyph with.
    fn icon_style(icon: &IconData) -> TextStyle {
        TextStyle::new()
            .font_size(24.0)
            .font_family(icon.font_family.clone().expect("a font family"))
    }

    #[test]
    fn icon_data_object_test() {
        assert_ne!(Icons::account_balance(), Icons::account_box());
        assert_eq!(
            format!("{:?}", Icons::account_balance()),
            "IconData(U+0E040)"
        );
    }

    #[test]
    fn icons_specify_the_material_font() {
        assert_eq!(Icons::clear().font_family.as_deref(), Some("MaterialIcons"));
        assert_eq!(
            Icons::search().font_family.as_deref(),
            Some("MaterialIcons")
        );
        assert_eq!(Icons::search().font_package, None);
    }

    #[test]
    fn certain_icons_and_their_variants_match_text_direction() {
        assert!(Icons::arrow_back().match_text_direction);
        assert!(Icons::arrow_back_rounded().match_text_direction);
        assert!(Icons::arrow_back_outlined().match_text_direction);
        assert!(Icons::arrow_back_sharp().match_text_direction);

        assert!(!Icons::access_time().match_text_direction);
        assert!(!Icons::access_time_rounded().match_text_direction);
        assert!(!Icons::access_time_outlined().match_text_direction);
        assert!(!Icons::access_time_sharp().match_text_direction);
    }

    #[test]
    fn adaptive_icons_are_correct_on_cupertino_platforms() {
        {
            for platform in CUPERTINO_PLATFORMS {
                let cell = AppCell::with_platform(Rc::new(TestPlatform::new().on(platform)));
                let app = cell.borrow();
                assert_eq!(Icons::adaptive().arrow_back(&app), Icons::arrow_back_ios());
                assert_eq!(
                    Icons::adaptive().arrow_back_outlined(&app),
                    Icons::arrow_back_ios_outlined()
                );
            }
        }
    }

    #[test]
    fn adaptive_icons_are_correct_on_non_cupertino_platforms() {
        {
            for platform in OTHER_PLATFORMS {
                let cell = AppCell::with_platform(Rc::new(TestPlatform::new().on(platform)));
                let app = cell.borrow();
                assert_eq!(Icons::adaptive().arrow_back(&app), Icons::arrow_back());
                assert_eq!(
                    Icons::adaptive().arrow_back_outlined(&app),
                    Icons::arrow_back_outlined()
                );
            }
        }
    }

    #[test]
    fn a_sample_of_code_points_is_the_one_the_dart_table_has() {
        for (icon, code_point) in [
            (Icons::ten_k(), 0xe000),
            (Icons::ten_k_sharp(), 0xe700),
            (Icons::ten_k_rounded(), 0xf4df),
            (Icons::ten_k_outlined(), 0xedf2),
            (Icons::r#loop(), 0xe3bb),
            (Icons::zoom_out_map_outlined(), 0xf4dd),
        ] {
            assert_eq!(icon.code_point, code_point);
            assert_eq!(icon.font_family.as_deref(), Some("MaterialIcons"));
        }
    }

    #[test]
    fn every_icon_of_the_samples_is_a_glyph_of_the_bundled_font() {
        {
            let cell = AppCell::new();
            let mut app = cell.borrow_mut();
            let fonts = installed_fonts(&mut app);
            let collection = app.get(fonts);
            let id = collection.family("MaterialIcons").expect("the icon family");
            for icon in [
                Icons::ten_k(),
                Icons::ac_unit(),
                Icons::local_taxi(),
                Icons::local_taxi_outlined(),
                Icons::local_taxi_rounded(),
                Icons::local_taxi_sharp(),
                Icons::zoom_out_sharp(),
                Icons::water_drop(),
                Icons::electric_bolt(),
                Icons::repeat_on(),
            ] {
                let glyph = char::from_u32(icon.code_point).expect("an icon code point");
                assert!(collection.get(id).covers(glyph), "{icon:?}");
            }
        }
    }

    #[test]
    fn installing_the_font_twice_registers_it_once() {
        {
            let cell = AppCell::new();
            let mut app = cell.borrow_mut();
            let fonts = installed_fonts(&mut app);
            install_material_icon_font(&mut app);
            assert_eq!(app.get(fonts).len(), 1);
        }
    }

    #[test]
    fn an_installed_icon_lays_out_as_one_glyph() {
        {
            let cell = AppCell::new();
            let mut app = cell.borrow_mut();
            let fonts = installed_fonts(&mut app);
            let icon = Icons::local_taxi();
            let glyph: String = char::from_u32(icon.code_point)
                .expect("an icon code point")
                .into();
            let mut painter = TextPainter::new();
            painter.set_text(Some(
                TextSpan::new()
                    .text(glyph)
                    .style(icon_style(&icon))
                    .into_span(),
            ));
            painter.set_text_direction(Some(TextDirection::Ltr));
            painter.layout(app.get_mut(fonts), 0.0, f64::INFINITY);
            assert!(painter.width() > 0.0 && painter.height() > 0.0);
            assert!(
                app.get_mut(fonts).take_unanswered().is_empty(),
                "the icon family and its glyph are covered by the bundled font"
            );
            painter.dispose();
        }
    }
}
